		panel.add(InitialHumidityText);

		JLabel IdealHumidityLabel = new JLabel("Ideal Moisture:");
		IdealHumidityLabel.setBounds(660, 60, 190, 25);
		panel.add(IdealHumidityLabel);

		JTextField IdealHumidityText = new JTextField(20);
		IdealHumidityText.setBounds(850, 60, 100, 25);
		panel.add(IdealHumidityText);

		JLabel IdealHumidityRangeLabel = new JLabel("Humidity Comfort Range:");
		IdealHumidityRangeLabel.setBounds(660, 100, 190, 25);
		panel.add(IdealHumidityRangeLabel);

		JTextField IdealHumidityRangeText = new JTextField(20);
		IdealHumidityRangeText.setBounds(850, 100, 100, 25);
		panel.add(IdealHumidityRangeText);

		JLabel HumidifierOnRateLabel = new JLabel("Humidifier On Rate:");
		HumidifierOnRateLabel.setBounds(660, 140, 190, 25);
		panel.add(HumidifierOnRateLabel);

		JTextField HumidifierOnRateText = new JTextField(20);
		HumidifierOnRateText.setBounds(850, 140, 100, 25);
		panel.add(HumidifierOnRateText);

		JLabel HumidifierOffRateLabel = new JLabel("Ambient Humidity Rate:");
		HumidifierOffRateLabel.setBounds(660, 180, 190, 25);
		panel.add(HumidifierOffRateLabel);

		JTextField HumidifierOffRateText = new JTextField(20);
		HumidifierOffRateText.setBounds(850, 180, 100, 25);
		panel.add(HumidifierOffRateText);

		JLabel CurrentHumidityLabel = new JLabel("Current Humidity:");
		CurrentHumidityLabel.setBounds(660, 220, 190, 25);
		panel.add(CurrentHumidityLabel);

		JLabel HumidifierIndicatorLabel = new JLabel("Humidifier:");
		HumidifierIndicatorLabel.setBounds(660, 260, 190, 25);
		panel.add(HumidifierIndicatorLabel);

		JPanel HumidifierIndicator = new JPanel();
		HumidifierIndicator.setBounds(850, 260, 25, 25);
		HumidifierIndicator.setBackground(Color.RED);
		panel.add(HumidifierIndicator);

		//Control buttons

		//Start and stop buttons.
		JButton StartButton = new JButton("Start");
		StartButton.setBounds(20, 360, 130, 30);
		panel.add(StartButton);

		JButton StopButton = new JButton("Stop");
		StopButton.setBounds(160, 360, 130, 30);
		StopButton.setEnabled(false);
		panel.add(StopButton);

		//Save button for save simulation
		JButton SaveButton = new JButton("Save");
		SaveButton.setBounds(500, 360, 130, 30);
		panel.add(SaveButton);

		//Load button for load simulation.
		JButton LoadButton = new JButton("Load");
		LoadButton.setBounds(640, 360, 130, 30);
		panel.add(LoadButton);


		//Pass necessary variables and instantiate required classes and objects.
		TemperatureControl tempControl = new TemperatureControl(IdealTempText, FurnaceRateText, 
				ACRateText, NoneRateText, CurrentTempLabel, FurnaceIndicator, ACIndicator);
		MoistureControl moistureControl = new MoistureControl(IdealMoistureText, IdealMoistureRangeText, 
				SprinklerOnRateText, SprinklerOffRateText, CurrentMoistureLabel, SprinklerIndicator);
		HumidityControl humidityControl = new HumidityControl(IdealHumidityText, IdealHumidityRangeText, 
				HumidifierOnRateText, HumidifierOffRateText, CurrentHumidityLabel, HumidifierIndicator);

		//Action listener for the start button.
		StartButton.addActionListener(e -> {
			if(!tempControl.isAlive() && !moistureControl.isAlive() && !humidityControl.isAlive()) {
				try {
					int InitialTemp = Integer.parseInt(InitialTempText.getText());
					int InitialMoisture = Integer.parseInt(InitialMoistureText.getText());
					int InitialHumidity = Integer.parseInt(InitialHumidityText.getText());


					tempControl.setCurrentTemp(InitialTemp);
					moistureControl.setCurrentMoisture(InitialMoisture);
					humidityControl.setCurrentHumidity(InitialHumidity);

					tempControl.start();
                    moistureControl.start();
                    humidityControl.start();

					StartButton.setEnabled(false);
					StopButton.setEnabled(true);
				} catch (NumberFormatException ex) {
					JOptionPane.showMessageDialog(panel, "Invalid input format (enter integers).");
				}
			} else {
				tempControl.pauseSimulation(false);
				moistureControl.pauseSimulation(false);
				humidityControl.pauseSimulation(false);

				StartButton.setEnabled(false);
				StopButton.setEnabled(true);
			}
		});

		//Action listener for save button.
		SaveButton.addActionListener(e -> {
			FileDialog fileDialog = new FileDialog((Frame) null, "Save Simulation Data", FileDialog.SAVE);
			fileDialog.setFilenameFilter((dir, name) -> name.endsWith(".txt"));
			fileDialog.setVisible(true);

			String FileName = fileDialog.getFile();
			String Directory = fileDialog.getDirectory();


			if (FileName != null && Directory != null) {

				String SimulationData = getSimulationData(tempControl, moistureControl, humidityControl);
				String FilePath = Directory + FileName;

				try (FileWriter fileWriter = new FileWriter(FilePath, false)){
					fileWriter.write(SimulationData);
				} catch (IOException ex) {
					JOptionPane.showMessageDialog(panel, "Saving error.");
				}
			}
		});

		//Action listener for load button.
		LoadButton.addActionListener(e -> {
			FileDialog fileDialog = new FileDialog((Frame) null, "Load Simulation Data", FileDialog.LOAD);
			fileDialog.setFilenameFilter((dir, name) -> name.endsWith(".txt"));
			fileDialog.setVisible(true);


			String FileName = fileDialog.getFile();
			String Directory = fileDialog.getDirectory();

			if (FileName != null && Directory != null) {
				StringBuilder SimulationData = new StringBuilder();
				String FilePath = Directory + FileName;

				try (BufferedReader bufferedReader = new BufferedReader(new FileReader(FilePath))) {
					String line;
					while ((line = bufferedReader.readLine()) != null) {
						SimulationData.append(line);
					}
				} catch (IOException ex) {
					JOptionPane.showMessageDialog(panel, "Loading error.");
				}

				if (SimulationData.length() > 0) {
					JOptionPane.showMessageDialog(panel, SimulationData.toString(), "Loaded Simulation", 
							JOptionPane.INFORMATION_MESSAGE);
				}
			}
		});

		//Action listener for stop button.
		StopButton.addActionListener(e -> {
            tempControl.pauseSimulation(true);
            moistureControl.pauseSimulation(true);
            humidityControl.pauseSimulation(true);

            StartButton.setEnabled(true);
            StopButton.setEnabled(false);
        });
	}
	/**
	 * Combines the simulation data from TemperatureControl, MoistureControl, HumidityControl objects
	 * into a single string.
	 * @param tempControl The TemperatureControl object providing temperature data.
	 * @param moistureControl The MoistureControl object providing moisture data.
	 * @param humidityControl The HumidityControl object providing humidity data.
	 * @return A formatted string with the combined simulation data.
	 */
	public static String getSimulationData(TemperatureControl tempControl, 
			MoistureControl moistureControl, HumidityControl humidityControl) {

		StringBuilder SimulationData = new StringBuilder();
		List<String> TempDataList = Arrays.asList(tempControl.SimulationData.toString().split("\n"));
		List<String> MoistureDataList = Arrays.asList(moistureControl.SimulationData.toString().split("\n"));
		List<String> HumidityDataList = Arrays.asList(humidityControl.SimulationData.toString().split("\n"));

		int MaxData = Math.max(TempDataList.size(), Math.max(MoistureDataList.size(), HumidityDataList.size()));


		for (int i = 0; i < MaxData; i++) {
			if (i < TempDataList.size()) {
				SimulationData.append(TempDataList.get(i)).append(", ");
			}
			if (i < MoistureDataList.size()) {
				SimulationData.append(MoistureDataList.get(i)).append(", ");
			}
			if (i < HumidityDataList.size()) {
				SimulationData.append(HumidityDataList.get(i)).append(", ");
			}
			SimulationData.append("\n");
		}

		return SimulationData.toString();
	}
}

public class HumidityControl extends Thread {

	private volatile boolean running = true;
	private volatile boolean pauseSimulation;

	private JTextField IdealHumidityText;
	private JTextField IdealHumidityRangeText;
	private JTextField HumidifierOnRateText;
	private JTextField HumidifierOffRateText;
	private JLabel CurrentHumidityLabel;
	private JPanel HumidifierIndicator;
	private int CurrentHumidity;
	private HumidifierMode humidifierMode;
	public StringBuilder SimulationData = new StringBuilder();

	/**
	 * Constructor to initialize HumidityControl object.
	 * @param IdealHumidityText Field with ideal humidity value.
	 * @param IdealHumidityRangeText Field with ideal humidity range.
	 * @param HumidifierOnRateText Field with humidifier on rate value.
	 * @param HumidifierOffRateText Field with humidifier off rate value.
	 * @param CurrentHumidityLabel Label to display current humidity value.
	 * @param HumidifierIndicator Panel to show on/off status of humidifier.
	 */
	public HumidityControl(JTextField IdealHumidityText, JTextField IdealHumidityRangeText, 
			JTextField HumidifierOnRateText, JTextField HumidifierOffRateText, 
			JLabel CurrentHumidityLabel, JPanel HumidifierIndicator) {
		this.IdealHumidityText = IdealHumidityText;
		this.IdealHumidityRangeText = IdealHumidityRangeText;
		this.HumidifierOnRateText = HumidifierOnRateText;
		this.HumidifierOffRateText = HumidifierOffRateText;
		this.CurrentHumidityLabel = CurrentHumidityLabel;
		this.HumidifierIndicator = HumidifierIndicator;
		this.humidifierMode = HumidifierMode.OFF;
		this.SimulationData = new StringBuilder();
	}

	/**
	 * Enum for representing modes of humidifier: ON and OFF.
	 */
	private enum HumidifierMode {
		ON, OFF
	}

	/**
	 * Setter for current humidity.
	 * @param CurrentHumidity The current humidity value to be set.
	 */
	public void setCurrentHumidity(int CurrentHumidity) {
		this.CurrentHumidity = CurrentHumidity;
	}

	/**
	 * Getter for current humidity.
	 * @return Returns current humidity value.
	 */
	public int getCurrentHumidity() {
		return CurrentHumidity;
	}

	/**
	 * Pauses simulation.
	 * @param pause Pauses or resumes simulation.
	 */
	public void pauseSimulation(boolean pause) {
		pauseSimulation = pause;
	}

	/**
	 * Stops the thread.
	 */
	public void stopThread() {
		running = false;
	}

	/**
	 * Simulation loop for running humidifier simulation.
	 */
	public void run() {

		while (running) {
			if (!pauseSimulation) {
				int IdealHumidity = Integer.parseInt(IdealHumidityText.getText());
				int IdealHumidityRange = Integer.parseInt(IdealHumidityRangeText.getText());
				int HumidifierOnRate = Integer.parseInt(HumidifierOnRateText.getText());
				int HumidifierOffRate = Integer.parseInt(HumidifierOffRateText.getText());

				if (CurrentHumidity < IdealHumidity - IdealHumidityRange) {
					humidifierMode = HumidifierMode.ON;
					CurrentHumidity += HumidifierOnRate;
				} else if (CurrentHumidity > IdealHumidity + IdealHumidityRange) {
					humidifierMode = HumidifierMode.OFF;
					CurrentHumidity -= HumidifierOffRate;
				} else {
					humidifierMode = HumidifierMode.OFF;
					CurrentHumidity -= HumidifierOffRate;
				}

				if (CurrentHumidity > 100) {
					CurrentHumidity = 100;
				} else if (CurrentHumidity < 0) {
					CurrentHumidity = 0;
				}

				CurrentHumidityLabel.setText("Current Humidity: " + CurrentHumidity);
				HumidifierIndicator.setBackground(humidifierMode == HumidifierMode.ON ? Color.GREEN : Color.RED);

				if (humidifierMode == HumidifierMode.OFF) {
                    HumidifierOffRateText.setBackground(Color.GREEN);
                } else {
                	HumidifierOffRateText.setBackground(Color.WHITE);
                }

				SimulationData.append("Humidity: ").append(CurrentHumidity)
                .append(", Humidifier Indicator: ").append(humidifierMode == HumidifierMode.ON ? "ON" : "OFF")
                .append('\n');

				try {
					Thread.sleep(3000);
				} catch (InterruptedException e) {
					break;
				}
			}
		}
	}
}

public class TemperatureControl extends Thread {

	private JTextField IdealTempText;
    private JTextField FurnaceRateText;
    private JTextField ACRateText;
    private JTextField NoneRateText;
    private JLabel CurrentTempLabel;
    private JPanel FurnaceIndicator;
    private JPanel ACIndicator;
    private int CurrentTemp;
    private HVACMode hvacMode;
    public StringBuilder SimulationData = new StringBuilder();

    private volatile boolean running = true;
    private volatile boolean pauseSimulation = false;

    /**
     * Constructor to initialize TemperatureControl object.
     * @param IdealTempText Field with ideal temperature value.
     * @param FurnaceRateText Field with furnace on rate value.
     * @param ACRateText Field with air-conditioner on rate value.
     * @param NoneRateText Field with ambient temperature increase rate value.
     * @param CurrentTempLabel Label to display current temperature value.
     * @param FurnaceIndicator Panel to show on/off status of furnace.
     * @param ACIndicator Panel to show on/off status of air-conditioner.
     */
    public TemperatureControl(JTextField IdealTempText, JTextField FurnaceRateText, 
    		JTextField ACRateText, JTextField NoneRateText, JLabel CurrentTempLabel, 
    		JPanel FurnaceIndicator, JPanel ACIndicator) {
    	this.IdealTempText = IdealTempText;
    	this.FurnaceRateText = FurnaceRateText;
		this.ACRateText = ACRateText;
		this.NoneRateText = NoneRateText;
		this.CurrentTempLabel = CurrentTempLabel;
		this.FurnaceIndicator = FurnaceIndicator;
		this.ACIndicator = ACIndicator;
		this.hvacMode = HVACMode.NONE;
    }

    /**
	 * Enum for representing modes of hvac: AC, FURNACE, and NONE.
	 */
    private enum HVACMode {
        FURNACE,
        AC,
        NONE
    }

    /**
	 * Setter for current temperature.
	 * @param CurrentTemp The current temperature value to be set.
	 */
    public void setCurrentTemp(int CurrentTemp) {
        this.CurrentTemp = CurrentTemp;
    }

    /**
	 * Getter for current temperature.
	 * @return Returns current temperature value.
	 */
    public int getCurrentTemp() {
        return CurrentTemp;
    }

    /**
	 * Pauses simulation.
	 * @param pause Pauses or resumes simulation.
	 */
    public void pauseSimulation(boolean pause) {
        pauseSimulation = pause;
    }

    /**
	 * Stops the thread.
	 */
    public void stopThread() {
        running = false;
    }

    /**
	 * Simulation loop for running hvac simulation.
	 */
    public void run() {
		while (running) {
			if (!pauseSimulation) {
				int IdealTemp = Integer.parseInt(IdealTempText.getText());
                int FurnaceRate = Integer.parseInt(FurnaceRateText.getText());
                int ACRate = Integer.parseInt(ACRateText.getText());
                int NoneRate = Integer.parseInt(NoneRateText.getText());

                int IdealTemperatureRange = 3; 

                if (CurrentTemp < IdealTemp - IdealTemperatureRange) {
                    hvacMode = HVACMode.FURNACE;
                    CurrentTemp += FurnaceRate;
                } else if (CurrentTemp > IdealTemp + IdealTemperatureRange) {
                    hvacMode = HVACMode.AC;
                    CurrentTemp -= ACRate;
                } else {
                    hvacMode = HVACMode.NONE;
                    CurrentTemp += NoneRate;
                }

                CurrentTempLabel.setText("Current Temperature: " + CurrentTemp);
                FurnaceIndicator.setBackground(hvacMode == HVACMode.FURNACE ? Color.GREEN : Color.RED);
                ACIndicator.setBackground(hvacMode == HVACMode.AC ? Color.GREEN : Color.RED);

                if (hvacMode == HVACMode.NONE) {
                    NoneRateText.setBackground(Color.GREEN);
                } else {
                    NoneRateText.setBackground(Color.WHITE);
                }
                SimulationData.append("Temperature: ").append(CurrentTemp)
                .append(", Furnace Indicator: ").append(hvacMode == HVACMode.FURNACE ? "ON" : "OFF")
                .append(", Air Conditioner Indicator: ").append(hvacMode == HVACMode.AC ? "ON" : "OFF")
                .append('\n');

				try {
					Thread.sleep(5000);
				} catch (InterruptedException e) {
					break;
				}
			}
		}
	}
}

public class MoistureControl extends Thread {

	private volatile boolean running = true;
    private volatile boolean pauseSimulation = false;
	private JTextField IdealMoistureText;
	private JTextField IdealMoistureRangeText;
	private JTextField SprinklerOnRateText;
	private JTextField SprinklerOffRateText;
	private JLabel CurrentMoistureLabel;
	private JPanel SprinklerIndicator;
	private int CurrentMoisture;
	private SprinklerMode sprinklerMode;
	public StringBuilder SimulationData = new StringBuilder();


	/**
	 * Constructor to initialize MoistureControl object.
	 * @param IdealMoistureText Field with ideal moisture value.
	 * @param IdealMoistureRangeText Field with ideal moisture range.
	 * @param SprinklerOnRateText Field with sprinkler on rate value.
	 * @param SprinklerOffRateText Field with sprinkler off rate value.
	 * @param CurrentMoistureLabel Label to display current moisture value.
	 * @param SprinklerIndicator Panel to show on/off status of sprinkler.
	 */
	public MoistureControl(JTextField IdealMoistureText, JTextField IdealMoistureRangeText, 
			JTextField SprinklerOnRateText, JTextField SprinklerOffRateText, 
			JLabel CurrentMoistureLabel, JPanel SprinklerIndicator) {
		this.IdealMoistureText = IdealMoistureText;
	    this.IdealMoistureRangeText = IdealMoistureRangeText;
	    this.SprinklerOnRateText = SprinklerOnRateText;
	    this.SprinklerOffRateText = SprinklerOffRateText;
	    this.CurrentMoistureLabel = CurrentMoistureLabel;
	    this.SprinklerIndicator = SprinklerIndicator;
	    this.sprinklerMode = SprinklerMode.OFF;
	    this.SimulationData = new StringBuilder();
	}

	/**
	 * Enum for representing modes of sprinkler: ON and OFF.
	 */
	private enum SprinklerMode{
		ON, OFF
	}

	/**
	 * Setter for current moisture.
	 * @param CurrentMoisture The current moisture value to be set.
	 */
	public void setCurrentMoisture(int CurrentMoisture) {
		this.CurrentMoisture = CurrentMoisture;
	}

	/**
	 * Getter for current moisture.
	 * @return Returns current moisture value.
	 */
	public int getCurrentMoisture() {
		return CurrentMoisture;
	}

	/**
	 * Pauses simulation.
	 * @param pause Pauses or resumes simulation.
	 */
	public void pauseSimulation(boolean pause) {
        pauseSimulation = pause;
    }

	/**
	 * Stops the thread.
	 */
	public void stopThread() {
		running = false;
	}

	/**
	 * Simulation loop for running sprinkler simulation.
	 */
	public void run() {
		while (running) {
			if (!pauseSimulation) {
				int IdealMoisture = Integer.parseInt(IdealMoistureText.getText());
			    int IdealMoistureRange = Integer.parseInt(IdealMoistureRangeText.getText());
			    int SprinklerOnRate = Integer.parseInt(SprinklerOnRateText.getText());
			    int SprinklerOffRate = Integer.parseInt(SprinklerOffRateText.getText());

				if (CurrentMoisture < IdealMoisture - IdealMoistureRange) {
					sprinklerMode = SprinklerMode.ON;
					CurrentMoisture += SprinklerOnRate;
				} else if (CurrentMoisture > IdealMoisture + IdealMoistureRange) {
					sprinklerMode = SprinklerMode.OFF;
					CurrentMoisture -= SprinklerOffRate;
