                const scrollLockPixels = (windowHeight * scrollLockDistance) / 100;

                if (distanceToAnchor <= scrollLockPixels) {
                    scrollToAnchor(nextAnchorOffset, distanceToAnchor, true);
                } else {
                    const freeScrollValue = distanceToAnchor - scrollLockPixels;
                    const newScrollOffset = scrollOffset + delta * freeScrollValue;
                    scrollToAnchor(newScrollOffset, freeScrollValue, false, () => {
                        scrollToAnchor(nextAnchorOffset, scrollLockPixels, true);
