        font-size: {font_size}px;
        font-family: {font_family};
    }}
""")
```

To allow users to change the font size and style, create options in your application's settings where users can pick a preferred font size and style. Then, dynamically update the stylesheets based on the user's selected preferences.

For example, create a font size slider and a font family combo box in your settings menu:

```python
from PyQt5.QtWidgets import QSlider, QComboBox

font_size_slider = QSlider(Qt.Horizontal)
font_size_slider.setRange(8, 24)
font_size_slider.setValue(font_size)
font_size_slider.valueChanged.connect(update_font_size)

font_family_combo_box = QComboBox()
font_family_combo_box.addItems(["Arial", "Courier", "Times New Roman"])
font_family_combo_box.setCurrentText(font_family)
font_family_combo_box.currentTextChanged.connect(update_font_family)
```

Define the `update_font_size()` and `update_font_family()` functions to update the application stylesheets dynamically based on user input:

```python
def update_font_size(new_font_size):
    global font_size
    font_size = new_font_size
    app.setStyleSheet(f"""
        * {{
            font-size: {font_size}px;
            font-family: {font_family};
        }}
    """)

def update_font_family(new_font_family):
    global font_family
    font_family = new_font_family
    app.setStyleSheet(f"""
        * {{
            font-size: {font_size}px;
            font-family: {font_family};
        }}
    """)
```

